import numpy as np
import math
import sys
import os

# Add project root to path
sys.path.append(os.path.abspath(os.path.join(os.path.dirname(__file__), "..")))
from fabrication.library import lamp_lib

# -----------------------------------------------------------------------------
# CHILD V42 (Catalog #107): THE T-SQUARE FRACTAL (Recursive Windows)
# -----------------------------------------------------------------------------
# Concept: A 2D fractal generated by recursively filling corners of a square.
#          Projected onto a sphere, it creates a grid of expanding/contracting windows.
# Parents: 106_apollonian_foam (Packing), 105_cantor_dust (Recursive).
# Math: Iterated Function System (Square corners).
# -----------------------------------------------------------------------------

def t_square_fractal(u, v, iterations=5):
    # Returns True if (u,v) is solid, False if void (window).
    # u, v are in [0, 1].
    
    # The T-Square is usually defined by adding squares.
    # Let's define it by removing the centers? No, that's Sierpinski Carpet.
    # T-Square fills the space.
    # Start: Center square.
    # Iteration 1: 4 smaller squares at corners.
    # Iteration 2: 12 smaller squares...
    
    # Let's use a coordinate check.
    # Map to [-1, 1]
    x = u * 2.0 - 1.0
    y = v * 2.0 - 1.0
    
    # Start with solid center square size s=0.5
    s = 0.5
    if abs(x) < s and abs(y) < s:
        return True # Solid center
        
    # Recursively check corners
    # Move origin to corners and scale up
    
    for i in range(iterations):
        # Identify quadrant
        sx = 1.0 if x > 0 else -1.0
        sy = 1.0 if y > 0 else -1.0
        
        # Shift origin to corner of current square
        # The corner of the square of size s is at (s, s) relative to center?
        # Center square size is s*2 (width). Corners at s.
        
        # New origin
        x -= sx * s
        y -= sy * s
        
        # Scale up
        x *= 2.0
        y *= 2.0
        
        # Check new center
        # But wait, T-square squares shrink by half each time.
        # By scaling coordinate by 2, we keep checking against size s=0.5.
        
        if abs(x) < 0.5 and abs(y) < 0.5:
            return True
            
    return False

def generate_child_v42(output_path, diameter=200.0, height=140.0, resolution=120, hole_diameter=14.0):
    print(f"Generating CHILD V42 (The T-Square Fractal): {output_path}")

    mount_hole_radius = hole_diameter / 2.0
    shell_thickness = 25.0
    
    max_dim = max(diameter, height)
    step = max_dim / resolution
    
    # Pad grid
    res_x = int(diameter / step) + 6
    res_y = int(diameter / step) + 6
    res_z = int(height / step) + 2
    
    grid = np.zeros((res_x, res_y, res_z), dtype=bool)
    
    radius = diameter / 2.0
    sphere_z_center = height - radius
    
    # ---------------------------------------------------------
    # FRACTAL GENERATION
    # ---------------------------------------------------------
    
    # T-Square normally fills space.
    # We want "Windows".
    # So we invert: only the boundary or specific iterations?
    # Let's simple map the T-Square pattern as "Solid", so gaps are void.
    
    for z_idx in range(res_z):
        z_mm = z_idx * step
        
        # Twist
        twist = z_mm * 0.03
        
        for x_idx in range(res_x):
            x_mm = (x_idx * step) - radius
            for y_idx in range(res_y):
                y_mm = (y_idx * step) - radius
                
                dist_xy = math.sqrt(x_mm**2 + y_mm**2)
                
                # Effective Z
                effective_z = z_mm
                if z_mm > (height - 10.0): effective_z = height - 10.0
                
                dist_sq = x_mm**2 + y_mm**2 + (effective_z - sphere_z_center)**2
                dist_spherical = math.sqrt(dist_sq)
                
                # 1. MOUNTING
                dz = effective_z - sphere_z_center
                term = radius**2 - dz**2
                curr_r = math.sqrt(term) if term > 0 else 0
                
                cap_check = lamp_lib.apply_solid_mounting_cap(
                    x_mm, y_mm, z_mm, dist_xy,
                    mount_z_start=(height - 4.0),
                    mount_hole_radius=mount_hole_radius,
                    cap_radius=curr_r
                )
                if cap_check is not None:
                    grid[x_idx,y_idx,z_idx] = cap_check
                    continue
                
                spider_check = lamp_lib.apply_spider_fitter(
                    x_mm, y_mm, z_mm, dist_xy,
                    mount_z_start=(height - 40.0),
                    outer_radius=radius
                )
                if spider_check is not None:
                    grid[x_idx,y_idx,z_idx] = spider_check
                    continue
                
                # 2. SHELL
                if z_mm < 4.0:
                    hand_radius = radius - shell_thickness
                    if dist_xy < radius and dist_xy > hand_radius:
                        grid[x_idx,y_idx,z_idx] = True
                        continue
                
                in_outer = dist_spherical <= radius
                in_inner = dist_spherical < (radius - shell_thickness)
                in_hand_zone = (dist_xy < (radius - shell_thickness)) and (z_mm < (height - 40.0))
                
                if in_outer and not in_inner and not in_hand_zone:
                    # 3. T-SQUARE LATTICE
                    
                    # Apply Twist
                    x_rot = x_mm * math.cos(twist) - y_mm * math.sin(twist)
                    y_rot = x_mm * math.sin(twist) + y_mm * math.cos(twist)
                    
                    # Map to U, V [0, 1]
                    # Map around cylinder/sphere
                    
                    # Equirectangular projection
                    # u = theta / 2pi
                    # v = (z - z_min) / (z_max - z_min)
                    # Or simply map x,y to U,V on top/bottom?
                    
                    # Let's use a cylindrical mapping for the sides.
                    
                    theta = math.atan2(y_rot, x_rot) # -pi to pi
                    u = (theta + math.pi) / (2.0 * math.pi)
                    
                    v = z_mm / height
                    
                    # Check Fractal
                    # Scale u, v to repeat the pattern?
                    # 4 repeats around
                    
                    u_scaled = (u * 4.0) % 1.0
                    v_scaled = (v * 2.0) % 1.0
                    
                    if t_square_fractal(u_scaled, v_scaled, iterations=4):
                        # Solid fractal
                        
                        # Add thickness via Gyroid intersection?
                        # Or just extrude.
                        # The fractal is the wall.
                        
                        # To make it 3D printable, we need to ensure the "corners" connect.
                        # T-Square is connected.
                        grid[x_idx,y_idx,z_idx] = True
                    else:
                        # Void
                        # Add a very sparse lattice to hold the floating bits?
                        # T-Square is a single connected component if built iteratively?
                        # Yes, squares touch at corners.
                        # However, with discrete sampling, corners might be missed.
                        
                        # Secondary lattice for safety
                        base_scale = 2.0 * math.pi / 15.0
                        g_val = np.sin(x_mm*base_scale) * np.cos(y_mm*base_scale) + \
                                np.sin(y_mm*base_scale) * np.cos(z_mm*base_scale) + \
                                np.sin(z_mm*base_scale) * np.cos(x_mm*base_scale)
                        
                        if abs(g_val) < 0.15:
                            grid[x_idx,y_idx,z_idx] = True
                        else:
                            grid[x_idx,y_idx,z_idx] = False
                        
                else:
                     grid[x_idx,y_idx,z_idx] = False

    # Post-Processing
    grid = lamp_lib.clean_voxel_grid(grid)
    vertices, faces = lamp_lib.extract_mesh_from_grid(grid, step, diameter, diameter)
    lamp_lib.write_binary_stl(output_path, vertices, faces)

if __name__ == "__main__":
    project_root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    output_dir = os.path.join(project_root, "fabrication/practical_design/FAVORITES/children")
    os.makedirs(output_dir, exist_ok=True)
    output_file = os.path.join(output_dir, "child_107_t_square_fractal.stl")
    
    if len(sys.argv) > 1: output_file = sys.argv[1]
    generate_child_v42(output_file)
